use std::time::{Duration, Instant};
use std::{env, process};

use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};
use Bostree::bostree::*;
use Bostree::test_tree_sanity;

fn cmp(a: &str, b: &str) -> i32 {
