use std::cell::RefCell;
use std::cmp::max;
use std::rc::{Rc, Weak};

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(String, Option<String>);

#[derive(Debug)]
pub struct BOSNode {
    pub key: String,
    pub data: Option<String>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub weak_ref_count: u32,
}

pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

fn parent(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    node.borrow().parent_node.as_ref().and_then(|p| p.upgrade())
}

fn is_left_child(parent: &Rc<RefCell<BOSNode>>, child: &Rc<RefCell<BOSNode>>) -> bool {
    parent
        .borrow()
        .left_child_node
        .as_ref()
        .map_or(false, |n| Rc::ptr_eq(n, child))
}

fn subtree_count(node: &Option<Rc<RefCell<BOSNode>>>) -> u32 {
    node.as_ref()
        .map(|n| {
            let b = n.borrow();
            b.left_child_count + b.right_child_count + 1
        })
        .unwrap_or(0)
}

fn child_depth(node: &Option<Rc<RefCell<BOSNode>>>) -> u32 {
    node.as_ref().map(|n| n.borrow().depth + 1).unwrap_or(0)
}

fn update_node(node: &Rc<RefCell<BOSNode>>) {
    let (left, right) = {
        let b = node.borrow();
        (b.left_child_node.clone(), b.right_child_node.clone())
    };
    let left_count = subtree_count(&left);
    let right_count = subtree_count(&right);
    let depth = max(child_depth(&left), child_depth(&right));
    let mut b = node.borrow_mut();
    b.left_child_count = left_count;
    b.right_child_count = right_count;
    b.depth = depth;
}

fn balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let b = node.borrow();
    child_depth(&b.right_child_node) as i32 - child_depth(&b.left_child_node) as i32
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        Self { root_node: None, cmp_function, free_function }
    }

    pub fn bostree_destroy(&mut self) {
        self.root_node = None;
    }

    pub fn bostree_node_count(&self) -> u32 {
        subtree_count(&self.root_node)
    }

    fn rotate_left(&mut self, p: Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let r = p.borrow().right_child_node.clone().expect("rotate_left needs right child");
        let old_parent = parent(&p);
        let r_left = r.borrow().left_child_node.clone();

        if let Some(op) = old_parent.clone() {
            if is_left_child(&op, &p) { op.borrow_mut().left_child_node = Some(r.clone()); }
            else { op.borrow_mut().right_child_node = Some(r.clone()); }
        } else {
            self.root_node = Some(r.clone());
        }
        r.borrow_mut().parent_node = old_parent.as_ref().map(Rc::downgrade);

        {
            let mut pb = p.borrow_mut();
            pb.right_child_node = r_left.clone();
        }
        if let Some(child) = r_left { child.borrow_mut().parent_node = Some(Rc::downgrade(&p)); }
        p.borrow_mut().parent_node = Some(Rc::downgrade(&r));
        r.borrow_mut().left_child_node = Some(p.clone());

        update_node(&p);
        update_node(&r);
        r
    }

    fn rotate_right(&mut self, p: Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let l = p.borrow().left_child_node.clone().expect("rotate_right needs left child");
        let old_parent = parent(&p);
        let l_right = l.borrow().right_child_node.clone();

        if let Some(op) = old_parent.clone() {
            if is_left_child(&op, &p) { op.borrow_mut().left_child_node = Some(l.clone()); }
            else { op.borrow_mut().right_child_node = Some(l.clone()); }
        } else {
            self.root_node = Some(l.clone());
        }
        l.borrow_mut().parent_node = old_parent.as_ref().map(Rc::downgrade);

        {
            let mut pb = p.borrow_mut();
            pb.left_child_node = l_right.clone();
        }
        if let Some(child) = l_right { child.borrow_mut().parent_node = Some(Rc::downgrade(&p)); }
        p.borrow_mut().parent_node = Some(Rc::downgrade(&l));
        l.borrow_mut().right_child_node = Some(p.clone());

        update_node(&p);
        update_node(&l);
        l
    }

    fn rebalance_from(&mut self, mut cur: Option<Rc<RefCell<BOSNode>>>) {
        while let Some(n) = cur {
            update_node(&n);
            let b = balance(&n);
            let mut top = n.clone();
            if b < -1 {
                let left = n.borrow().left_child_node.clone().unwrap();
                if balance(&left) > 0 { self.rotate_left(left); }
                top = self.rotate_right(n.clone());
            } else if b > 1 {
                let right = n.borrow().right_child_node.clone().unwrap();
                if balance(&right) < 0 { self.rotate_right(right); }
                top = self.rotate_left(n.clone());
            }
            cur = parent(&top);
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let node = Rc::new(RefCell::new(BOSNode {
            key,
            data,
            parent_node: None,
            left_child_node: None,
            right_child_node: None,
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            weak_ref_count: 0,
        }));

        if self.root_node.is_none() {
            self.root_node = Some(node.clone());
            return node;
        }

        let mut cur = self.root_node.clone().unwrap();
        loop {
            let cmp = (self.cmp_function)(&node.borrow().key, &cur.borrow().key);
            if cmp < 0 {
                let next = cur.borrow().left_child_node.clone();
                if let Some(n) = next { cur = n; } else {
                    cur.borrow_mut().left_child_node = Some(node.clone());
                    node.borrow_mut().parent_node = Some(Rc::downgrade(&cur));
                    self.rebalance_from(Some(cur));
                    return node;
                }
            } else {
                let next = cur.borrow().right_child_node.clone();
                if let Some(n) = next { cur = n; } else {
                    cur.borrow_mut().right_child_node = Some(node.clone());
                    node.borrow_mut().parent_node = Some(Rc::downgrade(&cur));
                    self.rebalance_from(Some(cur));
                    return node;
                }
            }
        }
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let mut target = node.clone();
        if target.borrow().left_child_node.is_some() && target.borrow().right_child_node.is_some() {
            let succ = bostree_next_node(&target).unwrap();
            {
                let mut tb = target.borrow_mut();
                let mut sb = succ.borrow_mut();
                std::mem::swap(&mut tb.key, &mut sb.key);
                std::mem::swap(&mut tb.data, &mut sb.data);
            }
            target = succ;
        }

        let child = {
            let b = target.borrow();
            if b.left_child_node.is_some() { b.left_child_node.clone() } else { b.right_child_node.clone() }
        };
        let par = parent(&target);
        if let Some(c) = child.clone() { c.borrow_mut().parent_node = par.as_ref().map(Rc::downgrade); }

        if let Some(p) = par.clone() {
            if is_left_child(&p, &target) { p.borrow_mut().left_child_node = child; }
            else { p.borrow_mut().right_child_node = child; }
        } else {
            self.root_node = child;
        }

        {
            let mut tb = target.borrow_mut();
            tb.parent_node = None;
            tb.left_child_node = None;
            tb.right_child_node = None;
            tb.left_child_count = 0;
            tb.right_child_count = 0;
            tb.depth = 0;
        }
        self.rebalance_from(par.or_else(|| self.root_node.clone()));
    }

    pub fn bostree_node_weak_unref(&mut self, node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
        let mut b = node.borrow_mut();
        if b.weak_ref_count > 0 { b.weak_ref_count -= 1; }
        Some(node.clone())
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut cur = self.root_node.clone();
        while let Some(n) = cur.clone() {
            let cmp = (self.cmp_function)(key, &n.borrow().key);
            if cmp == 0 { return Some(n); }
            cur = if cmp < 0 { n.borrow().left_child_node.clone() } else { n.borrow().right_child_node.clone() };
        }
        None
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut cur = self.root_node.clone();
        let mut idx = index;
        while let Some(n) = cur.clone() {
            let left = n.borrow().left_child_count;
            if idx < left { cur = n.borrow().left_child_node.clone(); }
            else if idx == left { return Some(n); }
            else { idx -= left + 1; cur = n.borrow().right_child_node.clone(); }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        fn rec(n: &Option<Rc<RefCell<BOSNode>>>, indent: usize) {
            if let Some(node) = n {
                rec(&node.borrow().right_child_node, indent + 4);
                println!("{:indent$}{} ({},{},{})", "", node.borrow().key, node.borrow().left_child_count, node.borrow().right_child_count, node.borrow().depth, indent = indent);
                rec(&node.borrow().left_child_node, indent + 4);
            }
        }
        rec(&self.root_node, 0);
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(mut n) = node.borrow().right_child_node.clone() {
        loop {
            let left = n.borrow().left_child_node.clone();
            if let Some(l) = left { n = l; } else { return Some(n); }
        }
    }
    let mut n = node.clone();
    while let Some(p) = parent(&n) {
        if is_left_child(&p, &n) { return Some(p); }
        n = p;
    }
    None
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(mut n) = node.borrow().left_child_node.clone() {
        loop {
            let right = n.borrow().right_child_node.clone();
            if let Some(r) = right { n = r; } else { return Some(n); }
        }
    }
    let mut n = node.clone();
    while let Some(p) = parent(&n) {
        if !is_left_child(&p, &n) { return Some(p); }
        n = p;
    }
    None
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut n = node.clone();
    while let Some(p) = parent(&n) {
        if !is_left_child(&p, &n) { counter += 1 + p.borrow().left_child_count; }
        n = p;
    }
    counter
}
